"""Igará's remote Linux helper. Invoked over SSH, never installed globally."""
import json
import os
import select
import signal
import stat
import struct
import subprocess
import sys
import time
from pathlib import Path


def workspace(build_id):
    # The identifier is generated by the client, but validate the boundary too.
    import uuid
    if str(uuid.UUID(build_id)) != build_id:
        raise ValueError("invalid build identifier")
    return Path.home() / ".cache" / "igara" / "builds" / build_id


def stop_group(process):
    try:
        os.killpg(process.pid, signal.SIGTERM)
    except ProcessLookupError:
        pass
    # Keep the leader unreaped during the grace period to avoid PID reuse.
    time.sleep(0.3)
    try:
        os.killpg(process.pid, signal.SIGKILL)
    except ProcessLookupError:
        pass
    process.wait()


def run(build_id, seconds, argv):
    interrupted = False

    def interrupt(_signum, _frame):
        nonlocal interrupted
        interrupted = True

    for signum in (signal.SIGHUP, signal.SIGINT, signal.SIGTERM):
        signal.signal(signum, interrupt)
    process = subprocess.Popen(argv, cwd=workspace(build_id), stdin=subprocess.DEVNULL,
                               start_new_session=True)
    deadline = time.monotonic() + seconds
    try:
        while True:
            if interrupted or time.monotonic() >= deadline:
                return 124
            readable, _, _ = select.select([sys.stdin.buffer], [], [], 0.1)
            if readable:
                # Any input (or EOF) revokes this attempt's execution lease.
                return 125
            # waitid with WNOWAIT observes completion without reaping the leader.
            status = os.waitid(os.P_PID, process.pid, os.WEXITED | os.WNOHANG | os.WNOWAIT)
            if status is not None:
                if status.si_code == os.CLD_EXITED:
                    return status.si_status
                return 128 + status.si_status
    finally:
        stop_group(process)


def artifact(build_id, relative):
    parts = relative.split("/")
    if not parts or any(part in ("", ".", "..") or "\\" in part for part in parts):
        raise ValueError("artifact must be a workspace-relative file")
    descriptor = os.open(workspace(build_id), os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
    try:
        for part in parts[:-1]:
            child = os.open(part, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW, dir_fd=descriptor)
            os.close(descriptor)
            descriptor = child
        file_descriptor = os.open(parts[-1], os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK,
                                  dir_fd=descriptor)
        with os.fdopen(file_descriptor, "rb") as source:
            metadata = os.fstat(source.fileno())
            if not stat.S_ISREG(metadata.st_mode) or metadata.st_nlink != 1:
                raise ValueError("artifact must be a regular file without hard links")
            # Fixed-size header: big-endian length and executable flag. Never paths.
            sys.stdout.buffer.write(struct.pack("!QB", metadata.st_size,
                                                bool(metadata.st_mode & 0o111)))
            remaining = metadata.st_size
            while remaining:
                chunk = source.read(min(65536, remaining))
                if not chunk:
                    raise ValueError("artifact changed while downloading")
                sys.stdout.buffer.write(chunk)
                remaining -= len(chunk)
            after = os.fstat(source.fileno())
            if (metadata.st_size, metadata.st_mtime_ns, metadata.st_ctime_ns) != (
                    after.st_size, after.st_mtime_ns, after.st_ctime_ns):
                raise ValueError("artifact changed while downloading")
    finally:
        os.close(descriptor)


if __name__ == "__main__":
    try:
        operation, build_id = sys.argv[1:3]
        if operation == "run":
            sys.exit(run(build_id, float(sys.argv[3]), json.loads(sys.argv[4])))
        elif operation == "artifact":
            artifact(build_id, sys.argv[3])
        else:
            raise ValueError("unknown helper operation")
    except Exception as error:
        print(f"remote helper: {error}", file=sys.stderr)
        sys.exit(126)
